SELECT p.gender, COUNT(DISTINCT CASE WHEN t.itemid IN (1001, 1002, 1003, 1004, 1005) AND t.charttime BETWEEN a.admittime AND a.dischtime THEN t.subject_id END) * 100.0 / COUNT(DISTINCT t.subject_id) AS proportion_of_patients_with_oral_antidiabetic_drug_first_72h, COUNT(DISTINCT CASE WHEN t.itemid IN (1001, 1002, 1003, 1004, 1005) AND t.charttime BETWEEN (a.dischtime - interval '48 hours') AND a.dischtime THEN t.subject_id END) - COUNT(DISTINCT CASE WHEN t.itemid IN (1001, 1002, 1003, 1004, 1005) AND t.charttime BETWEEN a.admittime AND (a.dischtime - interval '72 hours') THEN t.subject_id END) AS absolute_pp_change FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN transfers t ON a.subject_id = t.subject_id WHERE p.gender = 'F' AND EXTRACT(YEAR FROM age(CURRENT_DATE, p.dob)) BETWEEN 81 AND 91 AND t.hadm_id IN (SELECT hadm_id FROM diagnoses_icd WHERE icd_code IN ('250.0', '250.1')) GROUP BY p.gender;